import React, { useState, useEffect } from "react";
import { useNavigate } from "react-router-dom";
import { User, Edit, LogOut, Trophy, Zap, Flame, BookOpen, Award, X } from "lucide-react";
import Footer from "./footer";
import "../App.css";

const Profile = () => {
  const navigate = useNavigate();
  const [isEditing, setIsEditing] = useState(false);

  // 1. The state comes FIRST
  const [userData, setUserData] = useState({
    name: "Srija",
    email: "srija@gmail.com",
    grade: "Grade 10",
    school: "Govt High School",
    xp: 402, streak: 0, quizzes: 9, avgScore: "76%"
  });

  // 2. The effect comes SECOND (This is where it belongs!)
  useEffect(() => {
    const name = localStorage.getItem("userName");
    const email = localStorage.getItem("userEmail");
    const grade = localStorage.getItem("userGrade");

    if (name) {
      setUserData(prev => ({
        ...prev,
        name: name,
        email: email || "No Email",
        grade: grade || "Grade 10"
      }));
    }
  }, []);

  const [editForm, setEditForm] = useState(userData);

  const handleSave = () => {
    setUserData(editForm);
    setIsEditing(false);
  };

  const handleLogout = () => {
    localStorage.clear();
    navigate("/login");
  };

  return (
    <div className="page-wrapper">
       <div className="dashboard-container">
         <div className="profile-header-card">
           <div className="profile-banner"></div>
           <div className="profile-info-row">
             <div className="profile-avatar-box">
               <User size={64} color="#10b981" />
             </div>
             <div className="profile-text">
               <h1 className="profile-name">{userData.name}</h1>
               <p className="profile-subtext">{userData.grade} • {userData.email}</p>
             </div>
             <div className="profile-buttons">
               <button className="btn-edit" onClick={() => setIsEditing(true)}>
                 <Edit size={16} /> Edit Profile
               </button>
               <button className="btn-signout" onClick={handleLogout}>
                 <LogOut size={16} /> Sign Out
               </button>
             </div>
           </div>
         </div>
       </div>
       <Footer onNavigate={(path) => navigate(`/${path}`)} />
    </div>
  );
};

export default Profile;
